// provider-card seat. No unknown-namespace editor/YAML hint is shown.
if (row.entry.settingsNs === 'llm-cloudflare-gateway') {
  const gatewayOpen = !addOpen && editing?.provider === row.entry.provider
  const owner: GatewayProviderCardOwnerProps = {
    provider: row.entry, configured: row.configured, keyConfigured: keyConfiguredOf(row),
    // Explicit own adapter contract: the Gateway slot is a controlled
    // read-only card in the fork's one-open-card state, not an
    // independent expander.
    gatewayOpen,
    onGatewayToggle: (open: boolean) => {
      setSavedTarget(undefined)
      setAddOpen(false)
      setEditing(open ? target : undefined)
    },
  }
  return (
    <li key={row.entry.provider} className={styles['rowCard']} data-gateway-row>
      {error}
      {renderSlot('settings.models.provider-card', owner, { entryKey: row.entry.settingsNs })}
    </li>
  )
}
